import{_ as t,c as i,o as a,ag as r}from"./chunks/framework.DQvKz0xt.js";const m=JSON.parse('{"title":"Rive 中文文档","titleTemplate":"交互式动画的未来","description":"","frontmatter":{"layout":"home","title":"Rive 中文文档","titleTemplate":"交互式动画的未来","hero":{"name":"Rive 中文文档","text":"交互式动画的未来","tagline":"设计师创建，开发者集成，用户惊艳","actions":[{"theme":"brand","text":"快速开始","link":"/guide/introduction"},{"theme":"alt","text":"编辑器指南","link":"/editor/fundamentals/overview"}]},"features":[{"icon":"🎨","title":"编辑器 (Editor)","details":"在 Rive 编辑器中创建和动画化设计，使用强大的状态机构建逻辑和动画混合。","link":"/editor/fundamentals/overview"},{"icon":"📱","title":"应用运行时 (App Runtimes)","details":"开源库，支持在 Web、iOS、Android、Flutter、React Native 等平台实时渲染。","link":"/runtimes/overview"},{"icon":"🎮","title":"游戏运行时 (Game Runtimes)","details":"开源库，支持在 Unity、Unreal、Defold 和自定义游戏引擎中集成 Rive。","link":"/games/unity"},{"icon":"💻","title":"脚本 (Scripting)","details":"在一个协作编辑器中迭代代码、设计和动画（目前处于早期访问阶段）。","link":"/scripting/overview"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1774838907000}'),o={name:"index.md"};function n(l,e,s,d,c,v){return a(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="🌟-什么是-rive" tabindex="-1">🌟 什么是 Rive？ <a class="header-anchor" href="#🌟-什么是-rive" aria-label="Permalink to &quot;🌟 什么是 Rive？&quot;">​</a></h2><p>Rive 不仅仅是一个动画工具，它是一个<strong>实时的交互设计运行时（Runtime）</strong>。</p><p>与传统的视频或 GIF 不同，Rive 文件是矢量的、可交互的、体积极小的，并且可以直接在你的应用、游戏或网页中通过代码实时驱动。</p><div class="tip custom-block"><p class="custom-block-title">核心价值</p><p>设计师在 Rive 编辑器中看到什么效果，开发者在产品中就能实现完全一致的效果，彻底终结了&quot;还原度&quot;问题。</p></div><h2 id="🚀-为什么选择-rive" tabindex="-1">🚀 为什么选择 Rive？ <a class="header-anchor" href="#🚀-为什么选择-rive" aria-label="Permalink to &quot;🚀 为什么选择 Rive？&quot;">​</a></h2><ul><li><strong>状态机（State Machine）</strong>：在编辑器里就能定义交互逻辑，无需写一行代码即可实现复杂的按钮、角色动作切换</li><li><strong>全平台支持</strong>：支持 Web, iOS, Android, Flutter, Unity, Unreal, React Native 等</li><li><strong>性能卓越</strong>：相比 Lottie，Rive 拥有更高的渲染性能和更强的交互能力</li></ul><h2 id="📚-接下来该学什么" tabindex="-1">📚 接下来该学什么？ <a class="header-anchor" href="#📚-接下来该学什么" aria-label="Permalink to &quot;📚 接下来该学什么？&quot;">​</a></h2><ul><li>👉 <a href="/docs/editor/interface-overview/overview">编辑器界面概览</a></li><li>👉 <a href="/docs/editor/fundamentals/artboards">画板（Artboards）的概念</a></li><li>👉 <a href="/docs/editor/state-machine/overview">状态机入门</a></li></ul>',8)])])}const p=t(o,[["render",n]]);export{m as __pageData,p as default};
